from pathlib import Path
import json, subprocess
def secret(sid):
    return subprocess.check_output(['aws','secretsmanager','get-secret-value','--secret-id',sid,'--region','ap-southeast-3','--query','SecretString','--output','text'], text=True).strip()
p = Path('/opt/esafx/backoffice-service/.env.production')
text = p.read_text(encoding='utf-8')
raw = secret('esafx/production/backoffice-internal-token')
mail_token = json.loads(raw)['token'] if raw.startswith('{') else raw
svc_token = json.loads(secret('esafx/production/service-tokens'))['client']
def compose_env(v):
    return v.replace('$', '$$')
repl = {
  'ENVIRONMENT': 'production',
  'SMTP_ACCSUM_SECRET_ID': 'esafx/production/smtp-accsum',
  'CLIENT_SERVICE_URL': 'http://client:8000',
  'CORS_ORIGINS': 'https://backoffice.esandardev.com',
  'INTERNAL_SERVICE_TOKEN': compose_env(svc_token),
  'ACCSUM_MAIL_TOKEN': compose_env(mail_token),
}
lines = []
seen = set()
for line in text.splitlines():
    if '=' in line and not line.strip().startswith('#'):
        k = line.split('=', 1)[0]
        if k in repl:
            lines.append(f'{k}={repl[k]}')
            seen.add(k)
            continue
    lines.append(line)
for k, v in repl.items():
    if k not in seen:
        lines.append(f'{k}={v}')
p.write_text('\n'.join(lines) + '\n', encoding='utf-8')
print('env_ready', 'mail_token_len=' + str(len(mail_token)), 'svc_token_len=' + str(len(svc_token)))
